function validate([n, k, invocations]) {
  if (n < 1 || n > 100000) return 'n is between 1 and 100000.';
  if (k < 0 || k >= n) return 'k is a method number from 0 to n - 1.';
  if (invocations.length > 200000) return 'There are at most 200000 invocations.';
  const seen = new Set();
  for (const pair of invocations) {
    if (pair.length !== 2) return 'Each invocation is a pair [a, b].';
    const [a, b] = pair;
    if (a < 0 || a >= n || b < 0 || b >= n) return 'Every method number is between 0 and n - 1.';
    if (a === b) return 'A method never invokes itself.';
    const key = a + ',' + b;
    if (seen.has(key)) return 'Each invocation appears only once.';
    seen.add(key);
  }
  return null;
}

