function remainingMethods(n, k, invocations) {
  const graph = Array.from({ length: n }, () => []);
  for (const [caller, callee] of invocations) {
    graph[caller].push(callee);
  }
  const suspicious = new Array(n).fill(false);
  suspicious[k] = true;
  const stack = [k];
  while (stack.length > 0) {
    const method = stack.pop();
    for (const callee of graph[method]) {
      if (!suspicious[callee]) {
        suspicious[callee] = true;
        stack.push(callee);
      }
    }
  }
  for (const [caller, callee] of invocations) {
    if (!suspicious[caller] && suspicious[callee]) {
      return Array.from({ length: n }, (_, method) => method);
    }
  }
  const remaining = [];
  for (let method = 0; method < n; method++) {
    if (!suspicious[method]) {
      remaining.push(method);
    }
  }
  return remaining;
}

