function remainingMethods(n, k, invocations) {
  // Grow the suspicious set by sweeping over every call until a full sweep adds nothing.
  const bad = new Set([k]);
  let grew = true;
  while (grew) {
    grew = false;
    for (const [a, b] of invocations) {
      if (bad.has(a) && !bad.has(b)) { bad.add(b); grew = true; }
    }
  }
  const all = [...Array(n).keys()];
  const blocked = invocations.some(([a, b]) => !bad.has(a) && bad.has(b));
  return blocked ? all : all.filter(method => !bad.has(method));
}

