function generate(rand, size) {
  const n = size === 'large' ? 1000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 9);
  const k = Math.floor(rand() * n);
  const wanted = size === 'large' ? 1500 + Math.floor(rand() * 501) : Math.floor(rand() * Math.min(n + 3, n * (n - 1) + 1));
  const seen = new Set();
  let invocations = [];
  for (let tries = 0; invocations.length < wanted && tries < 20 * (wanted + 1); tries++) {
    const a = Math.floor(rand() * n);
    // In large projects most calls go a little further along, so the methods reachable from k lie mostly after it.
    const near = a + 1 + Math.floor(rand() * 30);
    const b = size === 'large' && rand() < 0.95 && near < n ? near : Math.floor(rand() * n);
    if (a === b || seen.has(a * n + b)) continue;
    seen.add(a * n + b);
    invocations.push([a, b]);
  }
  if (rand() < 0.5) {
    // Drop every call from a clean method into the suspicious set, so that the set can be removed.
    const out = Array.from({ length: n }, () => []);
    for (const [a, b] of invocations) out[a].push(b);
    const reached = new Array(n).fill(false);
    reached[k] = true;
    const queue = [k];
    for (let head = 0; head < queue.length; head++) {
      for (const b of out[queue[head]]) if (!reached[b]) { reached[b] = true; queue.push(b); }
    }
    invocations = invocations.filter(([a, b]) => reached[a] || !reached[b]);
  }
  return [n, k, invocations];
}
